  'tips.settings.subtitle': 'Wurld ನಿಂದ ಹೆಚ್ಚಿನದನ್ನು ಪಡೆಯುವುದು ಹೇಗೆ',
  'tips.settings.title': 'ಕಲಿಕೆಯ ಸಲಹೆಗಳು',
  'tips.shotAlt': 'ಸ್ಕ್ರೀನ್‌ಶಾಟ್: {title}',
  'tips.tapWords.details': 'ಅಂಡರ್‌ಲೈನ್ ಮಾಡಲಾದ ಪದಗಳು ಆ ಸಂದೇಶದಲ್ಲಿ ಕಲಿಯಲು ಯೋಗ್ಯವಾದ ಪದಗಳಾಗಿವೆ. ಅದರ ಅರ್ಥವನ್ನು ನೋಡಲು ಪದದ ಮೇಲೆ ಟ್ಯಾಪ್ ಮಾಡಿ. ಅದು ಹೇಗೆ ಕೇಳಿಸುತ್ತದೆ ಎಂದು ತಿಳಿಯಲು ಪದದ ನಂತರವಿರುವ ಸ್ಪೀಕರ್ ಐಕಾನ್ ಮೇಲೆ ಟ್ಯಾಪ್ ಮಾಡಿ, ಮತ್ತು ಅದನ್ನು ಉಳಿಸಲು ಬಲಭಾಗದಲ್ಲಿರುವ ಫ್ಲ್ಯಾಶ್‌ಕಾರ್ಡ್ ಬಟನ್ ಒತ್ತಿ. ಉಳಿಸಿದ ಪದಗಳು ನಿಮ್ಮ ಫ್ಲ್ಯಾಶ್‌ಕಾರ್ಡ್‌ಗಳು ಮತ್ತು ಅಭ್ಯಾಸದ ರಸಪ್ರಶ್ನೆಗಳಲ್ಲಿ ಮತ್ತೆ ಬರುತ್ತವೆ. ಕಾರ್ಡ್‌ನ ಎಡಭಾಗದಲ್ಲಿರುವ ? ಚಿಹ್ನೆಯು ಪದಗುಚ್ಛವನ್ನು ವಿವರಿಸುತ್ತದೆ (ಮುಂದಿನ ಟಿಪ್ ನೋಡಿ).',
  'tips.tapWords.summary': 'ಅಂಡರ್‌ಲೈನ್ ಮಾಡಲಾದ ಪದದ ಅರ್ಥ ತಿಳಿಯಲು, ಅದನ್ನು ಕೇಳಲು ಮತ್ತು ನಿಮ್ಮ ಫ್ಲ್ಯಾಶ್‌ಕಾರ್ಡ್‌ಗಳಿಗೆ ಸೇರಿಸಲು ಅದರ ಮೇಲೆ ಟ್ಯಾಪ್ ಮಾಡಿ.',
  'tips.tapWords.title': 'ಕೇಳಲು ಅಥವಾ ಉಳಿಸಲು ಪದವನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ',
  'tips.tryIt': 'ಪ್ರಯತ್ನಿಸಿ',
  'tips.write.details': 'ಚಾಟ್‌ನಲ್ಲಿರುವ ಪ್ರತಿಯೊಬ್ಬರೂ ನಿಮ್ಮ ಸಂದೇಶವನ್ನು ಅವರು ಆಯ್ಕೆ ಮಾಡಿದ ಭಾಷೆಯಲ್ಲಿ ಓದುತ್ತಾರೆ, ಆದ್ದರಿಂದ {practice} ನಲ್ಲಿ ಬರೆಯುವುದು ಸಂಭಾಷಣೆಯನ್ನು ನಿಧಾನಗೊಳಿಸುವುದಿಲ್ಲ. ಏನಾದರೂ ತಪ್ಪಾಗಿದ್ದರೆ, ನಿಮ್ಮ ಸಂದೇಶ ಕಳುಹಿಸುವ ಮುನ್ನ Wurld ತಿದ್ದುಪಡಿ ಮಾಡಿದ ಆವೃತ್ತಿಯನ್ನು ಸೂಚಿಸುತ್ತದೆ, ಮತ್ತು ನೀವು ಯಾವುದನ್ನು ಕಳುಹಿಸಬೇಕೆಂದು ಆಯ್ಕೆ ಮಾಡಬಹುದು.',
  'tips.write.example': 'ಸಣ್ಣದಾಗಿ ಪ್ರಾರಂಭಿಸಿ: ಒಂದು ಶುಭಾಶಯ, ಧನ್ಯವಾದ ಅಥವಾ {practice} ನಲ್ಲಿ ಒಂದು ಪದದ ಉತ್ತರ ಎಲ್ಲವೂ ಲೆಕ್ಕಕ್ಕೆ ಬರುತ್ತದೆ.',
  'tips.write.summary': 'ಸಾಧ್ಯವಾದಾಗಲೆಲ್ಲಾ {practice} ನಲ್ಲಿ ಉತ್ತರಿಸಿ. ಪ್ರತಿಯೊಬ್ಬರೂ ನಿಮ್ಮ ಸಂದೇಶವನ್ನು ಅವರವರ ಭಾಷೆಯಲ್ಲಿ ಓದುತ್ತಾರೆ.',
